<script setup>
import {ref,onMounted} from 'vue'
import App from './App.vue'
import {auth,adminFetch,authRequest,acceptSession} from './adminApi.js'
const ready=ref(false),setup=ref(false),error=ref(''),busy=ref(false)
const username=ref(''),password=ref(''),confirmPassword=ref(''),setupKey=ref('')
async function init(){ready.value=false;error.value='';try{const status=await adminFetch('/api/auth/status');if(!status.ok)throw Error('Не удалось связаться с API');setup.value=(await status.json()).setup_required;if(!setup.value){const me=await adminFetch('/api/auth/me');if(me.ok)acceptSession(await me.json());else if(me.status!==401)throw Error('Не удалось проверить вход')}ready.value=true}catch(e){error.value=e.message}}
async function submit(){if(busy.value)return;error.value='';if(setup.value&&password.value!==confirmPassword.value){error.value='Пароли не совпадают';return}busy.value=true;try{acceptSession(await authRequest('/api/auth/'+(setup.value?'setup':'login'),{username:username.value,password:password.value,...(setup.value?{setup_key:setupKey.value}:{})}));setup.value=false;password.value='';confirmPassword.value='';setupKey.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(init)
</script>
<template>
<App v-if="ready && auth.user" />
<main v-else class="login-shell"><section class="login-card"><div class="login-brand">NOVA <span>ADMIN</span></div><template v-if="!ready"><h1>Подключение к админке</h1><p v-if="error" class="alert" role="alert">{{error}}</p><p v-else>Проверка подключения…</p><button v-if="error" class="primary-btn" @click="init">Повторить</button></template><template v-else><h1>{{setup?'Создание администратора':'Вход в админку'}}</h1><p v-if="setup">Задайте логин и пароль для управления сайтом.</p><p v-if="auth.notice" role="status">{{auth.notice}}</p><p v-if="error" class="alert" role="alert">{{error}}</p><form @submit.prevent="submit"><fieldset :disabled="busy"><label v-if="setup">Ключ первоначальной настройки<input v-model="setupKey" type="password" autocomplete="off" required><small>ADMIN_API_KEY из файла .env. Он нужен только для создания первого администратора.</small></label><label>Логин<input v-model="username" required minlength="3" maxlength="64" pattern="[a-zA-Z0-9_.\-]{3,64}" autocomplete="username" autocapitalize="none"></label><label>Пароль<input v-model="password" required type="password" minlength="12" maxlength="256" :autocomplete="setup?'new-password':'current-password'"><small v-if="setup">От 12 до 256 символов.</small></label><label v-if="setup">Повторите пароль<input v-model="confirmPassword" required type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><button class="primary-btn">{{busy?'Подождите…':setup?'Создать администратора':'Войти'}}</button></fieldset></form></template></section></main>
</template>
<style scoped>
.login-shell{min-height:100vh;display:grid;place-items:center;padding:24px;background:#eef4f0;}.login-card{background:white;border:1px solid #dce7df;border-radius:18px;padding:32px;width:min(480px,100%);}.login-brand{color:#276b4e;font-size:28px;font-weight:800;}.login-brand span{font-size:13px;}h1{font-size:25px;margin:24px 0;}fieldset{border:0;padding:0;display:grid;gap:20px;min-width:0;}label{display:grid;gap:8px;font-size:14px;}input{padding:12px;border:1px solid #cadbd0;border-radius:8px;max-width:100%;min-width:0;}small,p{font-size:13px;line-height:1.7;color:#60756a;}
</style>
